            sellerId,
            warehouseId: warehouse.id
          }
        }
      }
    });
    variantId = variant.id;

    // 3. Create Order
    const order = await prisma.order.create({
      data: {
        userId,
        status: 'PENDING_PAYMENT',
        subtotal: 1000,
        shippingFee: 0,
        discount: 0,
        total: 1000,
        paymentMethod: 'WALLET',
        packages: {
          create: {
            sellerId,
            warehouseId: warehouse.id,
            status: 'PENDING',
            lines: {
              create: {
                variantId,
                quantity: 1,
                unitPrice: 1000
              }
            }
          }
        }
      }
    });
