  }

async getSellerBalance(sellerId: string, status?: LedgerStatus, client = prisma) {
    const aggregation = await client.sellerLedgerEntry.aggregate({
      where: { 
        sellerId,
        ...(status ? { status } : {})
      },
      _sum: {
        amount: true
      }
    });

    return (aggregation._sum.amount as unknown as Decimal) || new Decimal(0);
  }

